Constructs a `Polytope` geometric constraint system of the regular tetrahedron.
"""
function Tetrahedron(; pinned_vertices=Vector{Int}([]))::Polytope 
    return Polytope([[1,2,3], [2,3,4], [1,2,4], [1,3,4]], Matrix([1/sqrt(3) 0 0; -sqrt(3)/6 1/2 0; -sqrt(3)/6 -1/2 0; 0 0 sqrt(6)/3]'); pinned_vertices=pinned_vertices)
end

